import math
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st

from solution import get_max_triples


def reference(n):
    # Obviously-correct brute force directly from spec:
    # a[i] = i*i - i + 1 for 1 <= i <= n, count i<j<k with sum % 3 == 0
    a = [i * i - i + 1 for i in range(1, n + 1)]
    cnt = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if (a[i] + a[j] + a[k]) % 3 == 0:
                    cnt += 1
    return cnt


def comb3(m):
    if m < 3:
        return 0
    return m * (m - 1) * (m - 2) // 6


# ---- explicit examples from spec + hand-derived valid inputs ----

def test_example_n5():
    assert get_max_triples(5) == 1


def test_n1_returns_zero():
    assert get_max_triples(1) == 0


def test_n2_returns_zero():
    assert get_max_triples(2) == 0


def test_n3_returns_zero():
    # a = [1,3,7], 1+3+7=11 not multiple of 3
    assert get_max_triples(3) == 0


def test_n4_returns_one():
    # a = [1,3,7,13], only (1,7,13)=21 is 0 mod 3
    assert get_max_triples(4) == 1


def test_n6_returns_four():
    assert get_max_triples(6) == 4


def test_n7_returns_ten():
    assert get_max_triples(7) == 10


def test_n8_returns_eleven():
    assert get_max_triples(8) == 11


def test_n9_returns_21():
    assert get_max_triples(9) == 21


def test_small_n_return_int_not_none():
    for n in (1, 2, 3, 4, 5):
        r = get_max_triples(n)
        assert isinstance(r, int), f"n={n} should return int, got {type(r)}"
        assert r is not None


# ---- property-based tests against reference model ----

@given(st.integers(min_value=1, max_value=12))
def test_matches_brute_force(n):
    assert get_max_triples(n) == reference(n)


@given(st.integers(min_value=1, max_value=30))
def test_result_within_bounds(n):
    r = get_max_triples(n)
    assert isinstance(r, int)
    assert 0 <= r <= comb3(n)


@given(st.integers(min_value=1, max_value=30))
def test_monotone_non_decreasing(n):
    assume(n >= 1)
    # adding an element can only add triples, never remove
    assert get_max_triples(n + 1) >= get_max_triples(n)


@given(st.integers(min_value=1, max_value=50))
def test_matches_residue_count_model(n):
    # Independent residue computation: a[i] % 3 for i=1..n
    residues = [(i * i - i + 1) % 3 for i in range(1, n + 1)]
    c0 = sum(1 for v in residues if v == 0)
    c1 = sum(1 for v in residues if v == 1)
    c2 = sum(1 for v in residues if v == 2)
    # spec array never yields residue 2; check that invariant too
    assert c2 == 0
    assert c0 + c1 == n
    expected = comb3(c0) + comb3(c1) + comb3(c2)
    # cross-check residue model itself agrees with brute force
    assert expected == reference(n) if n <= 12 else True
    assert get_max_triples(n) == expected


@given(st.integers(min_value=1, max_value=50))
def test_no_triples_when_fewer_than_three(n):
    # For n < 3 there are no i<j<k, count must be 0
    assume(n < 3)
    assert get_max_triples(n) == 0


@given(st.integers(min_value=3, max_value=50))
def test_increment_bounded_by_pairs(n):
    # New triples introduced by element n+1 are at most C(n,2)
    r_n = get_max_triples(n)
    r_np1 = get_max_triples(n + 1)
    assert 0 <= r_np1 - r_n <= n * (n - 1) // 2
